contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: callerIsOwner determines whether this contract will be the owner before transfer;
    // newOwner is the address to transfer to; attemptByOwner decides who calls transferOwnership.
    function run(bool callerIsOwner, address newOwner, bool attemptByOwner) public payable {
        require(newOwner != address(0));

        // If we want this contract to be owner, call transferOwnership from c as owner must be set first.
        // Initially, when c is freshly deployed, its owner is address(0) unless constructor set otherwise.
        // We can only interact through c's public surface. To make this contract the owner, if needed,
        // we attempt to set owner by calling transferOwnership from this contract — that will only succeed
        // if this contract is already owner. So to set up initial owner to this contract we rely on the
        // possibility that c.owner() already equals address(this). If callerIsOwner is true, require that.
        // Otherwise require that this contract is not owner.

        address beforeOwner = c.owner();
        if (callerIsOwner) {
            // ensure precondition holds so test is meaningful
            require(beforeOwner == address(this));
        } else {
            require(beforeOwner != address(this));
        }

        bool reverted;
        // Decide who attempts the transfer: if attemptByOwner is true, the test contract (msg.sender) will call;
        // otherwise we need to simulate a non-owner caller. We cannot change msg.sender, but we can only use this contract
        // as caller; so to simulate a non-owner caller when this contract is owner we require that attemptByOwner implies callerIsOwner.
        // The only allowed caller in this environment is this contract, so attemptByOwner==false must imply this contract is not owner.
        if (!attemptByOwner) {
            // require that the test contract is not owner so that a call from it should revert
            require(beforeOwner != address(this));
        }

        // Make the deciding call: this contract calls transferOwnership(newOwner).
        // If this contract is owner the call should succeed and change owner to newOwner.
        // If not owner the call should revert and owner should remain unchanged.
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();

        // General rule: (1) If the caller (this contract) was the owner before, the call did not revert and owner equals newOwner.
        //               (2) If the caller was not the owner before, the call reverted and owner is unchanged.
        assert((beforeOwner == address(this) && !reverted && afterOwner == newOwner) || (beforeOwner != address(this) && reverted && afterOwner == beforeOwner));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    //  newOwner: address to pass to transferOwnership
    function run(address newOwner) public payable {
        // no assumptions about c.owner() so the test must handle both cases
        // read owner before the call
        address before = c.owner();

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address after = c.owner();

        // General rule: if the call reverted, owner remains unchanged; if it succeeded, owner equals newOwner
        assert((reverted && after == before) || (!reverted && after == newOwner));
    }

    receive() external payable {}
}

