contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // param: an address to set as owner (may be zero). We will attempt to transfer ownership to it
    // and then call owned() from this contract to observe whether it reverts depending on owner.
    function run(address candidate) public payable {
        require(true);

        // record original owner
        address ownerBefore = c.owner();

        // Try transferring ownership from this contract (msg.sender for calls to c is this contract).
        // transferOwnership may revert if this contract is not the owner; catch that.
        bool transferReverted;
        try c.transferOwnership(candidate) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // owner after attempted transfer
        address ownerAfter = c.owner();

        // Now attempt to call owned() which uses onlyOwner modifier. Capture whether it reverts.
        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        // General rule:
        // 1) If transferOwnership succeeded then ownerAfter == candidate.
        // 2) If transferOwnership reverted then ownerAfter == ownerBefore.
        // 3) owned() call reverts iff ownerAfter != address(this).
        assert(
            // relation between transfer result and owner change
            ((transferReverted && ownerAfter == ownerBefore) || (!transferReverted && ownerAfter == candidate))
            // and owned() reverts exactly when this contract is not ownerAfter
            && (ownedReverted == (ownerAfter != address(this)))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to transfer ownership to `candidate`. We observe owner before and after,
    // and whether transferOwnership and owned() reverted. The rule ties these together.
    function run(address candidate) public payable {
        require(true);

        // observe original owner via public getter
        address ownerBefore = c.owner();

        // try transferOwnership(candidate) and record revert status
        bool transferReverted;
        try c.transferOwnership(candidate) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // observe owner after attempt
        address ownerAfter = c.owner();

        // try calling owned() (onlyOwner) and record revert status
        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        // General invariant:
        // - If transfer succeeded then ownerAfter == candidate and owned() should not revert (since this contract is the caller and transfer made it owner).
        // - If transfer reverted then ownerAfter == ownerBefore and owned() reverts exactly when ownerBefore != address(this).
        assert(
            (
                !transferReverted && ownerAfter == candidate && ownedReverted == false
            ) || (
                transferReverted && ownerAfter == ownerBefore && ownedReverted == (ownerBefore != address(this))
            )
        );
    }

    receive() external payable {}
}
